refuse to let someone else’s success make me feel unsuccessful.","I am building a successful future through consistency.","I am proud of all I have accomplished and excited for what lies ahead.","My rest today prepares me for success tomorrow.","I recognize my achievements without comparison.","My goals matter, and I work toward them with passion.","I am consistent in taking action toward my goals.","I reflect on my goals and progress.","I am willing to put in the effort to succeed.","I celebrate every small win on my journey.","I build clarity by reviewing and refining my goals.","I honor my accomplishments, no matter the size.","I can build routines that support my goals.","I choose progress over perfection and celebrate each small win.","I am committed to my goals, even on hard days.","I embrace risks as part of success.","I am becoming the person I need to be for my goals.","I celebrate my achievements without guilt.","I measure success by joy and integrity.","I respect the effort I make toward my goals.","I follow goals that matter to me.","I eliminate what distracts me from my goals.","I feel accomplished when I take action.","I can release goals that no longer reflect who I am.","I am building the habits that support my success.","I celebrate the success of others.","I take full responsibility for my success.","I believe my dreams are worth the effort.","I continue working toward my goals even when the outcome is uncertain.","I am patient and trust the process of achieving my goals.","I move steadily toward my goals.","I am ready to make progress toward my goals today.","My work is valuable, and my goals are valid.","I learn from failure, and I learn from success.","I create my own path to success.","I am willing to take the next step toward my goals.","I take small actions toward my goals every day when I can.","I am creating success on my own terms.","I am willing to stay with my goal until it is complete.","I build success through patience and effort.","My success is built on consistent effort and belief in myself.","I set goals that respect my time, energy, and abilities.","I stay true to my values while building success.","I turn my goals into clear actions.","I remind myself why my goal matters to me.","I welcome failure as a part of the process of success.","I can develop the skills needed for my goals.","My mistakes are stepping stones to greater achievements.","I allow small successes to encourage me.","I know success takes time and effort.","I believe I can achieve more than I have achieved so far.","I take my goals seriously and make time for them.","I honor my dreams by making them achievable.","I create success without burnout.","I can be successful without rushing or stressing.","I do not need a guarantee of success before I begin.","I give myself time to adjust to new goals.","I can rest without giving up on my goals.","My actions today align with my goals and values.","I let my goals evolve with me.","I forgive myself for setting impossible goals.","I can keep my goals in mind while adjusting my approach.","I allow myself to enjoy my achievements, big and small.","I am open to constructive feedback that helps me grow and succeed.","I can work toward my goals and enjoy my life at the same time.","I actively work toward meaningful goals.","I do not rush my healing or success.","I set goals based on my values, not other people’s expectations.","I can turn my dreams into practical goals.","I choose realistic goals that fit my life.","I break big goals into manageable steps.","I am allowed to change my goals and discover new dreams.","I am allowed to have goals that matter deeply to me.","I use my time to support my goals.","I believe my dreams and goals are possible.","I do not judge my path because I have not reached my goals yet."]},{"title":"Relationships","lines":["I am my own best friend.","My integrity builds strong, respectful relationships.","I love talking to people and hearing different points of view.","I am present with loved ones.","I grow meaningful relationships through care and effort.","I bring presence and love into my relationships.","I am there for my friends in good times and bad.","I am worthy of deep, loving, and meaningful relationships.","I find peace in the company of loved ones.","I am committed to nurturing the relationships that matter most to me.","I cherish the moments spent with loved ones.","I am brave enough to make new friends.","I know how to be a good friend.","I show patience to the people around me.","I release the need to understand every reason why a relationship ended.","I deserve healthy and loving relationships.","I show love and appreciation to my friends regularly.","I learn to forgive each day.","I am open to forming new friendships and relationships.","I am worthy of relationships where I am respected and valued.","I make time for the relationships that bring joy and growth.","I deserve relationships in which my needs and boundaries are respected.","I am confident in expressing my needs and setting healthy boundaries.","My intuition guides me toward healthy connections.","I approach relationships with understanding and care.","I treat strangers with the same kindness I show loved ones.","I embrace new friendships and deepen existing ones.","My relationships grow stronger with kindness and respect.","My truth strengthens my relationships.","I release my attachment to relationships that are no longer part of my life.","Every day, I create space for connection and joy in my relationships.","I feel comfortable and at ease while communicating with others.","I forgive, and I feel free.","I trust that I am becoming the right person for the relationship I desire.","I can lean on my loved ones and share my feelings openly without judgment.","I let go of past hurts and approach relationships with fresh eyes.","I am learning to be a better friend to myself.","I forgive myself and others, and I am free from the weight of past relationships.","I choose relationships that are healthy and supportive.","I deserve respect, peace, and healthy connections.","I release expectations about how a past relationship should have ended.","I listen to other people’s opinions with patience and ease.","I choose to be fully present with the people around me.","I am worthy of love that feels safe, steady, and genuine.","I enjoy meeting new people and making new friends.","I appreciate the warmth of friendship.","I deserve healthy love and genuine support.","I am a good friend and treat others with kindness.","I communicate openly and honestly in my relationship.","My friends can count on me.","Each day, I encounter good people and am grateful.","I create meaningful memories with my loved ones.","I am patient and understanding with my loved ones.","I nurture my friendships and create lasting bonds.","I earn trust by showing up with honesty.","I am building a loving relationship with myself.","I deserve relationships built on mutual trust and respect.","I honor my relationships by showing up with honesty and compassion.","I cherish my friendships and invest time and energy into them.","I laugh and have fun with my friends.","I feel calm when I am among people that I do not know.","I choose relationships that allow me to be myself.","I choose relationships that respect my boundaries.","My relationships are built on authenticity and respect.","I can choose what is right for me while still caring about the people around me.","I respect the opinions of others, but I have my own.","I allow my needs to have a place in my relationships."]},{"title":"Health","lines":["I celebrate my body and all it allows me to do.","I thank my body for carrying me today.","I balance hard work with healthy breaks.","I choose nourishing foods that support my body.","My body knows how to relax, and I follow its lead.","I choose rest and recovery when my body needs it.","I am committed to my emotional and physical health.","I nurture my mental and emotional health.","I make time to care for my mind, body, and emotions.","I am grounded and safe in my body.","I am grateful for my body and treat it with love.","I am at peace with my body and its natural processes.","I create a healthy balance between effort and rest.","I am moving toward a healthier and more peaceful self.","My mental health matters more than productivity.","I deserve time to recharge my mind and body.","I focus on what nourishes me physically and emotionally.","I release negative thoughts about my health.","I let my body soften and my mind settle.","I move my body with joy and gratitude.","I create a safe space for my mental health.","I deserve a healthy work-life balance.","I carry forward only what nourishes me.","I allow my body and mind to recharge.","My health is my priority, and I invest in it daily.","I am patient with my health journey and trust the process.","My mind and body are deeply connected.","I am thankful for my body and all it does for me.","My health and happiness matter.","I accept and love my body just the way it is.","My mind, body, and energy come back to center.","I am aware of my breath and my body.","I am patient and gentle with my body.","I respect and honor my body.","I honor the rhythms of my body and mind.","I am present in my body and mind.","I deserve a healthy mind and body.","I take care of my mind and body with kindness.","I hydrate my body and nurture it with care.","I breathe deeply and allow my body to relax.","I release all negative judgments about my body.","I relax my shoulders and release tension from my body.","I prioritize my mental health and well-being.","I listen to the messages my body sends me.","I can take care of my body and mind.","I make space for what nourishes me.","I am filled with gratitude for my body’s resilience and strength.","I am creating a healthier relationship with myself.","I’m grateful for the food that nourished me.","I let my body feel supported.","I can feel uncomfortable while learning to make healthier choices.","I eat good food, move my body, and get enough rest.","I embrace daily movement and exercise with joy.","My body knows how to heal and restore itself.","I pay attention to the sensations in my body.","I am committed to living a healthy and balanced life.","I deserve to take care of my mental health.","My health is my greatest wealth, and I nurture it with care.","I make choices that support my health and happiness.","I am calm, centred, and at ease in my body.","My body, mind, and soul are worthy of care.","I enjoy nourishing food, peaceful moments, and laughter.","I give my body the rest it needs.","I am releasing tension from every part of my body.","I do the daily little things that contribute to my healthy lifestyle.","I accept my past while creating a healthier present.","I am open to learning new ways to support my health.","I allow my mind and body to slow down.","I honor my body and nurture it with healthy choices.","I am listening to my body and honoring its needs.","I release tension from my body one breath at a time.","My body deserves relaxation and care.","I am developing healthy habits every day.","I celebrate the small wins in my health journey.","I allow my body to rest fully.","I manage stress in healthy and productive ways.","I listen when my body and mind need rest.","I give myself permission to rest, recover, and restore my energy.","My body thanks me for slowing down."]},{"title":"Money","lines":["I am worthy of financial abundance.","I am wise with money and manage it well.","I learn from my past financial mistakes and make wiser decisions in the present.","My calm mind allows me to make wise financial decisions.","I build wealth step by step.","I build prosperity by staying consistent and disciplined.","My financial future is bright.","I develop wealthy habits.","I receive money, I give money.","I am committed to financial growth.","I am grateful for the financial security that I have.","I make confident money decisions.","I allow myself to enjoy the success I’ve earned.","I create prosperity for myself and the people that I love.","I am a wise and responsible steward of my financial resources.","I grow my financial security through wise choices.","I am on my way to prosperity.","I am capable of achieving my financial goals.","I trust myself with money.","I build abundance through patience.","I am satisfied with the money that I have.","I choose abundance over scarcity.","I am someone who sees abundance in the smallest things.","I lead with value, and abundance follows.","I am in control of my finances, and I make empowered choices.","I make wise financial decisions.","I give freely and receive abundantly.","I am creating a life of abundance, and I am grateful for the journey.","My financial goals are achievable and realistic.","I am committed to saving money and building a strong financial foundation.","Every day, I am getting closer to my financial goals.","I am financially resilient.","I am calm and confident about money.","I create wealth with intention.","I am financially capable and resourceful.","My financial situation is improving every day.","I am capable of creating financial stability and security for myself.","I handle finances with clarity and calm.","I release comparison around finances.","Every day, I am becoming more financially secure.","I allow money to work for me.","I receive money with joy, gratitude, and confidence.","I spend my money wisely, for the things I love, and I feel great about it.","I use money to create a life I love.","Today, I am taking confident steps toward financial freedom.","I release fear around money.","I manage money with balance and intention.","I am at peace with my finances and my future.","I am open to new income streams.","I use the money that I have for good purposes.","I create abundance through effort and consistency.","I am disciplined in managing my finances.","I am grateful for the big sums and for the small sums too.","I open my heart to receive abundance.","With each step that I make, I move closer to prosperity.","I deserve comfort and financial ease.","My actions create prosperity.","Every day, I am closer to financial freedom.","My abundance benefits others.","I welcome abundance, comfort, and simple joys.","I am in charge of my financial future.","I make decisions that support my financial and personal growth.","I am confident in managing money.","I welcome abundance without guilt.","My efforts bring me financial rewards.","My hard work is creating a prosperous future.","I know that I am able to handle any financial challenge that comes my way.","I let go of limiting beliefs about money.","I take practical steps toward prosperity in all forms.","I deserve financial freedom.","I earn money doing meaningful work.","I am resourceful and find creative solutions to improve my financial situation.","I honor my financial progress.","I am open to financial learning and growth.","I feel safe and secure with money.","I am able to recognize the abundance around me.","My actions align with my financial aspirations.","I take consistent steps toward financial stability.","I have everything I need to create abundance.","I believe abundance is possible for me.","I trust my ability to create wealth.","I have a healthy relationship with money.","I welcome financial balance.","I believe in myself and my financial success.","I am excited about my financial future.","I build wealth through smart choices.","I am patient and consistent with money goals.","I am grateful, I am abundant, I am enough.","I release all financial worries."]},{"title":"Everyday","lines":["My thoughts pass through like clouds in the sky.","I nurture my inner world with compassion and care.","I am moving forward at my own pace.","I embrace optimism and remind myself that I’m doing my best.","I stay connected to my daily experiences.","I am secure in myself, and I do not need constant reassurance.","I am allowed to follow my own path.","I feel balanced and stable, even when life feels uncertain or busy.","I remain steady even when life shifts.","My forgiveness brings me freedom and emotional well-being.","I give my best without expecting perfection.","I choose hope as I look toward the future.","I can choose a more balanced way to look at myself.","I do not need immediate results to keep going.","I am open to discovering what gives my life purpose.","I treat myself with kindness when things do not go as planned.","I am open to new ideas and ways of thinking.","I trust that my efforts matter.","I prioritize tasks that truly matter.","I begin again without shame.","I recognize that my feelings are important.","I honor my pace and trust the process.","I give myself permission to work toward what I want.","I can start again tomorrow if today feels too hard.","My emotions are valid, and I honor them with care.","I have everything I need to take the next step.","I am present with the people I care about.","I let myself enjoy life at my own pace.","I let this day unfold with warmth and ease.","I am in control of my schedule and make time for what matters most.","I am fully present in this moment.","I choose rest, not resistance.","I am not alone on this path.","I slow down and listen to my needs.","I no longer carry what isn’t mine.","I do not need all the answers right now.","I honor the feelings of my younger self.","I release expectations and embrace the present moment.","I take control of what depends on me.","I do my best with what I have right now.","I release comparison and return to myself.","I allow my needs to matter when I make choices.","I can pause before answering and listen to myself.","I meet myself with kindness.","I am embracing my journey with an open heart.","I can choose a helpful response instead of a fearful one.","I keep my promises to myself.","I honor my limits and take time for self-care.","I can find strength even when I do not feel strong.","I can return to what matters to me.","I choose understanding over harsh self-criticism.","I keep my schedule manageable.","I am a doer, not just a dreamer.","I am creating a life I love, one choice at a time.","My emotions come and go like waves.","I express my needs clearly and assertively.","I believe I am stronger than my circumstances.","I can ask for advice without giving away my own judgment.","I celebrate the journey, not just the destination.","I welcome new parts of myself with openness.","I can move forward even when I do not have all the answers.","I can be honest about my weaknesses without being cruel to myself.","I know that I can handle an unexpected change and keep moving forward.","I am at ease sharing my perspective.","I celebrate kindness, both given and received.","I focus on doing what I can today.","I accept responsibility for what is mine and release what is not.","I am still standing, and that matters.","I believe my future holds promise.","I am ready to make room for new experiences.","I don’t have to solve every problem today.","I am adventurous and willing to try new things.","I see the good in others and myself.","I believe in the power of kindness to change the world.","I am patient with life’s timing.","I stay focused on my priorities.","I choose paths that align with my values and true self.","I use self-compassion to move past regret.","I feel my feet on the ground and return to the moment.","I am allowed to pause, think, and find the right words.","I respect the decisions I make for my life.","I look toward my future with hope and curiosity.","I allow myself to recharge without guilt.","I stop trying to control everything.","I welcome moments of fun, laughter, and connection.","I trust in my ability to cope with whatever comes my way.","I start fresh from this moment onward.","I am proud of my voice and what it represents.","I am in control of my attitude and actions.","I am allowed to be myself without seeking everyone’s approval.","I am whole without needing to hold on.","I can let go of the need to compare myself with others.","I begin before I feel ready.","I notice distractions and gently return to my priorities.","I am hopeful, strong, and ready for today.","I allow today to be complete.","I approach everyday activities with greater attention.","I am exactly where I need to be right now.","I create space between my thoughts and my emotions.","I allow rest to be part of my regular routine.","My journey has value, even when it looks different from others.","I choose reflection over self-criticism.","I feel more at ease when I stop trying to be someone else.","I trust myself to make the right decision for me.","I carry hope with me and continue moving forward each day.","I prioritize my needs without guilt or hesitation.","I can take a break without feeling guilty.","I allow today to unfold gently and naturally.","I believe in the power of hope and perseverance.","I speak kindly to myself when I make a mistake.","I can stay patient while I work through this.","I notice my surroundings before reaching for a distraction.","I can build a new direction through small actions.","I am comfortable being different from others.","I can make one useful choice right now.","I choose kindness even when it’s hard.","I am proud of the small steps I took.","I approach today with mindfulness.","I can say no without explaining every detail.","I can make choices for myself without unnecessary guilt.","I am conscious of the impact of my choices.","My mind is free, flexible, and full of creative ideas.","I believe new possibilities can appear with time.","I remember the things I have done well.","I am excited about the opportunities today brings.","I celebrate small, meaningful moments.","I choose to nurture my inner child today.","I am not defined by moments of self-doubt.","I release patterns that no longer serve me.","I believe that my future can reflect the effort I am making today.","I allow myself to heal from disappointment.","I don’t need to finish everything—just begin.","I notice my feelings without letting them control me.","I support myself with kindness.","I slow down and take one moment at a time.","My inner voice matters more than outer noise.","I trust clarity to unfold in its time.","I give myself permission to take breaks when needed.","I am reliable and self-disciplined.","I choose a thoughtful response over an emotional reaction.","I can adjust my plan and continue.","I treat myself with curiosity instead of criticism.","I allow my thoughts to slow down.","I can trust my judgment while considering my options.","I am becoming my own biggest supporter, one day at a time.","I am committed to living honestly.","I take one useful step at a time toward what matters to me.","I can take responsibility without criticizing myself.","I honor time spent alone and with others.","I remain patient when I cannot see the full result yet.","I can disagree with someone without doubting myself.","I create clarity by slowing down.","I can recognize where I need to make a change.","I choose connection over comparison.","I am patient and understanding with others.","I stop denying what I know is true.","I release doubt and embrace self-trust.","I embrace discomfort as a teacher.","I can feel tired and still be strong.","I choose pleasure in the simple moments.","I accept the qualities that make me different from others.","I have the power to redirect my thoughts.","I allow myself to feel good today.","I can figure things out as I go.","I am more than my current circumstances.","I welcome the good that this day may bring.","I value my effort and celebrate my wins.","I can protect my time without apology.","I am becoming someone I love.","I welcome change with curiosity and openness.","I give myself grace as I move through the day.","I release the stress I no longer need to carry.","I welcome each day as a new opportunity.","I can stay steady while I work out what to do next.","I enjoy the company of those I love.","I can change direction without seeing it as a failure.","I focus on the reasons I want to keep going.","I can find something enjoyable in an ordinary day.","I am not my thoughts—I am the observer of my thoughts.","I trust my journey, even when it moves slowly.","My imperfections make me human, not unworthy.","My heart remains open to the light and promise of the future.","I find balance between doing and being.","I spend time on interests that I genuinely enjoy.","I honor others by being honest with them.","I release the need to rush and allow myself to savour the day.","I live in alignment with my values.","I honor my feelings while remaining grounded in the present.","I approach today with an open mind and a hopeful heart.","I recognize that every experience can add to what I know.","I am here, and I am paying attention.","I am letting go of what no longer serves me.","I am persistent, and I keep going.","I welcome today’s surprises with an open mind.","I accept that some things can wait.","I enjoy my surroundings instead of rushing past them.","I believe that my circumstances can change over time."]}]
"""#

    static let library: [Focus] = (try? JSONDecoder().decode([Focus].self, from: Data(libraryData.utf8))) ?? []

    private static let libraryLines = Set(library.flatMap(\.lines))
    static func isLibrary(_ line: String) -> Bool { libraryLines.contains(line) }

    /// The one persisted topic choice used by the app, widgets, and notification scheduler.
    static var selectedTopics: [String] {
        get { SharedState.defaults.stringArray(forKey: SharedState.Key.affirmationTopics) ?? [] }
        set { SharedState.defaults.set(newValue, forKey: SharedState.Key.affirmationTopics) }
    }

    /// User-facing wording stays personal while the source topic IDs continue to match the dataset.
    static func topicDisplayTitle(_ sourceTitle: String) -> String {
        switch sourceTitle {
        case "Self-esteem": "Self-worth"
        case "Safety": "Feeling safe"
        default: sourceTitle
        }
    }

    // MARK: Topic based delivery

    /// An empty topic selection means all available affirmation topics. The chosen topics (and the
    /// user's own lines) are dealt round-robin, so consecutive days alternate between topics instead
    /// of working through one whole topic before the next.
    static func topicRotation(focusTitles: [String], premium: Bool) -> [String] {
        let deleted = Set(SharedState.defaults.stringArray(forKey: SharedState.Key.deletedAffirmations) ?? [])
        let includeOwn = premium && (focusTitles.isEmpty || focusTitles.contains("Your own"))
        let chosenFocuses = focusTitles.isEmpty ? library.map(\.title) : focusTitles.filter { $0 != "Your own" }
        var lists = library.filter { chosenFocuses.contains($0.title) }
            .map { $0.lines.filter { !deleted.contains($0) } }
        if includeOwn {
            lists.append(SharedState.defaults.stringArray(forKey: SharedState.Key.customAffirmations) ?? [])
        }
        let longest = lists.map(\.count).max() ?? 0
        return (0..<longest).flatMap { index in lists.compactMap { index < $0.count ? $0[index] : nil } }
    }

    static func feedRotation(focusTitles: [String], premium: Bool) -> [String] {
        topicRotation(focusTitles: focusTitles, premium: premium)
    }

    /// Single quote source for Home, both widget families, and scheduled notifications.
    /// `occurrence` varies only the quote when a user has multiple reminders in one day.
    static func dailyLine(on date: Date = .now, occurrence: Int = 0, premium: Bool) -> String {
        dailyLine(on: date, occurrence: occurrence, focusTitles: selectedTopics, premium: premium)
    }

    /// Variant for observable app state. Home reads its selected topics through `AffirmationList`
    /// so SwiftUI invalidates the quote immediately when the user changes topics.
    static func dailyLine(on date: Date = .now, occurrence: Int = 0,
                          focusTitles: [String], premium: Bool) -> String {
        let list = topicRotation(focusTitles: focusTitles, premium: premium)
        guard !list.isEmpty else { return "" }
        let day = max(0, localDayNumber(date))
        return list[(day + occurrence) % list.count]
    }

    /// Whole local days since 1 Jan 2001: one number from midnight to midnight, wherever the phone
    /// is. `ordinality(of: .day, in: .era)` turned over at midnight UTC instead (5 PM in
    /// California), so Home, computed at the current time, ran one quote ahead of the widget and
    /// notifications, which are computed at the day's midnight.
    private static func localDayNumber(_ date: Date) -> Int {
        let cal = Calendar.current
        let origin = cal.date(from: DateComponents(year: 2001, month: 1, day: 1)) ?? .distantPast
        return cal.dateComponents([.day], from: cal.startOfDay(for: origin),
                                  to: cal.startOfDay(for: date)).day ?? 0
    }

    // MARK: Display

    /// Library lines go through the String Catalog; the user's own words are shown verbatim.
    static func text(_ line: String) -> Text {
        if line.isEmpty { return Text(loc: "No affirmations available") }
        return isLibrary(line) ? Text(loc: line) : Text(verbatim: line)
    }

    /// `text(_:)` for non-SwiftUI callers (notifications), in the in-app language rather than the
    /// device's — the widget forces that same language, so the two never disagree.
    static func display(_ line: String) -> String {
        isLibrary(line) ? localized(line) : line
    }

    /// A String Catalog lookup in the in-app language. `String(localized:)` would follow the
    /// device language instead, which the in-app picker can override.
    static func localized(_ key: String) -> String {
        L10n.localized(key)
    }
}
